/**
 * Pokémon Species Database
 * -------------------------
 * Every entry the Species field's autocomplete/picker can suggest: National Dex number,
 * species name, an optional Regional Demonym, an optional Form Name, and typing.
 *
 * A single species can have multiple entries, one per Regional Variant or official form
 * that carries its own typing (Alolan Meowth, Origin Forme Giratina, Zen Mode Darmanitan,
 * and so on). Each entry has a stable `id` so a saved Pokémon can remember exactly which
 * one was picked (and have it re-highlighted if the picker is reopened), independent of
 * array order.
 *
 * Fields are kept separate on purpose. Species name, demonym, and form name are never
 * pre-joined into one string. The picker builds its subtitle from them at render time:
 *   - both demonym and form  -> "Demonym · Form"
 *   - demonym only           -> "Demonym"
 *   - form only              -> "Form"
 *   - neither                -> no subtitle
 *
 * Regional Demonym is only ever one of the fixed regional-origin labels (Kantonian Form,
 * Alolan Form, Galarian Form, etc.), and every entry for a species that HAS regional
 * variants gets one, including that species' original form, so all of them read
 * consistently in the picker. Form Name is for official in-game alternate-forme names
 * (Origin Forme, Zen Mode, Crowned Sword, ...) unrelated to regional origin.
 *
 * This is a seed set covering the worked examples from the v25 spec, proving out the
 * schema end-to-end. The remaining ~1020 species (plain, single-entry, no demonym/form)
 * still need to be added from the full National Dex list.
 *
 * `games` lists the Game Preset keys (icons/game-icons.js) this exact entry could
 * actually be caught, hatched, or otherwise obtained in. A cosmetic-only form/forme
 * (Vivillon patterns, Unown letters, Alcremie flavors, Deoxys formes...) carries the
 * same list as its base species, since the games it can appear in don't depend on
 * which one you have. gameKeysForPokemon() in js/ribbon-eligibility.js checks a
 * Pokemon's Origin Game, Last Game, and per-game moveset entries against this before
 * trusting them, so a game the species could never have been in doesn't count toward
 * Ribbon/Mark eligibility.
 *
 * `evolvesFrom` holds another entry's own `id` for whatever species this one evolves
 * from, left unset on a base form with no pre-evolution. It can also be an array of ids
 * for a species reachable from more than one pre-evolution (Gholdengo from either
 * Gimmighoul form; Mothim from any Burmy cloak, unlike Wormadam which stays cloak-matched)
 * -- most entries only ever need a single id. speciesLineageIds() in
 * js/ribbon-eligibility.js walks this back through however many stages a line has, so a
 * Pokemon's Ribbon/game eligibility can rest on an earlier stage's availability, not just
 * its current one -- a Ribbon only obtainable pre-evolution, in a game the current
 * evolved form never existed in, still counts. Branching lines (Eevee's many
 * Eeveelutions) just mean multiple entries share the same evolvesFrom. Never point this at
 * a LATER evolution than the entry itself, or at anything that (directly or through its
 * own chain) evolves back into this entry -- both would create a loop.
 */

